<?php
$total = supplier_rows($filters, true);
$rows = supplier_rows($filters);
$kpis = supplier_kpis();
$pages = max(1, (int) ceil($total / $filters['per_page']));
$start = $total ? (($filters['page'] - 1) * $filters['per_page']) + 1 : 0;
$end = min($filters['page'] * $filters['per_page'], $total);
?>
<div class="customer-heading supplier-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Suppliers <span>&rsaquo;</span> <b>All Suppliers</b></div><h1>Suppliers</h1></div><a href="index.php?page=admin&amp;section=suppliers-add" class="btn btn-primary customer-add-button">+ Add Supplier</a></div>
<div class="row g-3 supplier-kpis"><?php foreach ($kpis as $label => $value): ?><div class="col-sm-6 col-xl-3"><div class="admin-panel supplier-kpi supplier-kpi-<?= e(strtolower(str_replace(' ', '-', $label))) ?>"><span class="supplier-kpi-icon"><?= in_array($label, ['Total Purchases', 'Outstanding Amount'], true) ? 'Rs.' : '◎' ?></span><div><span><?= e($label) ?></span><strong><?= in_array($label, ['Total Purchases', 'Outstanding Amount'], true) ? 'Rs. ' . number_format($value, 2) : number_format($value) ?></strong><small><?= $label === 'Total Suppliers' ? 'All Time' : ($label === 'Active Suppliers' ? ($total ? number_format(($value / $total) * 100, 1) . '% of Total' : 'No suppliers yet') : 'Purchasing module pending') ?></small></div></div></div><?php endforeach; ?></div>
<div class="admin-panel supplier-filters-panel"><form class="supplier-filter-bar" method="get"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="suppliers"><label>Search<input class="form-control" name="search" value="<?= e($filters['search']) ?>" placeholder="Search by name, contact, email..."></label><label>Status<select class="form-select" name="status"><option value="">All</option><option value="active" <?= $filters['status'] === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $filters['status'] === 'inactive' ? 'selected' : '' ?>>Inactive</option></select></label><label>From Date<input class="form-control" type="date" name="from" value="<?= e($filters['from']) ?>"></label><label>To Date<input class="form-control" type="date" name="to" value="<?= e($filters['to']) ?>"></label><a class="btn btn-light filter-reset" href="index.php?page=admin&amp;section=suppliers">Reset</a></form></div>
<div class="admin-panel supplier-list-panel"><div class="customer-list-heading"><h2>Suppliers List</h2></div><div class="table-responsive"><table class="table admin-table supplier-table"><thead><tr><th>#</th><th>Supplier Name</th><th>Contact Person</th><th>Phone</th><th>Email</th><th>Products</th><th>Total Purchases (Rs.)</th><th>Outstanding (Rs.)</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if (!$rows): ?><tr><td colspan="10" class="empty-table">No suppliers found. Add a supplier to begin.</td></tr><?php else: foreach ($rows as $index => $row): $products = supplier_products_for((int) $row['id']); ?><tr><td><?= $start + $index ?></td><td><div class="customer-name"><span class="customer-avatar"><?= e(strtoupper(substr($row['name'], 0, 1))) ?></span><span><strong><?= e($row['name']) ?></strong><small><?= e($row['supplier_code']) ?></small></span></div></td><td><?= e($row['contact_person'] ?: '-') ?></td><td><?= e($row['phone']) ?></td><td><?= e($row['email'] ?: '-') ?></td><td><span class="supplier-product-count"><?= count($products) ?></span><small class="supplier-product-preview"><?= e(implode(', ', array_slice(array_column($products, 'product_name'), 0, 2))) ?><?= count($products) > 2 ? '...' : '' ?></small></td><td>0.00</td><td>0.00</td><td><span class="status-badge status-<?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><div class="action-links supplier-actions"><button type="button" class="supplier-view-products" aria-label="View supplier" title="View supplier" data-supplier-name="<?= e($row['name']) ?>" data-supplier-contact="<?= e($row['contact_person'] ?: '-') ?>" data-supplier-phone="<?= e($row['phone']) ?>" data-supplier-email="<?= e($row['email'] ?: '-') ?>" data-supplier-status="<?= e(ucfirst($row['status'])) ?>" data-supplier-products="<?= e(json_encode($products)) ?>">&#128065;</button><a aria-label="Edit supplier" title="Edit supplier" href="index.php?page=admin&amp;section=suppliers-edit&amp;id=<?= (int) $row['id'] ?>">&#9998;</a><form method="post" action="index.php?page=admin&amp;section=suppliers-delete&amp;id=<?= (int) $row['id'] ?>" onsubmit="return confirm('Mark this supplier as inactive?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button type="submit" aria-label="Delete supplier" title="Delete supplier">&#128465;</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div><div class="customer-table-footer"><span>Showing <?= $start ?> to <?= $end ?> of <?= $total ?> suppliers</span><?php if ($pages > 1): ?><nav><ul class="pagination pagination-sm mb-0"><?php for ($number = 1; $number <= $pages; $number++): ?><li class="page-item <?= $number === $filters['page'] ? 'active' : '' ?>"><a class="page-link" href="index.php?page=admin&amp;section=suppliers&amp;p=<?= $number ?>&amp;per_page=<?= $filters['per_page'] ?>"><?= $number ?></a></li><?php endfor; ?></ul></nav><?php endif; ?><label class="items-per-page">Items per page:<select onchange="var u=new URL(window.location.href);u.searchParams.set('per_page',this.value);u.searchParams.delete('p');window.location.href=u.toString();"><option>10</option><option>25</option><option>50</option></select></label></div></div>
